import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"🔬 科学快报 | 2026年7月31日（事后重建版 · 第 ? 期）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-31.md","filePath":"science-log/src/reconstructed/2026-07-31.md"}'),n={name:"science-log/src/reconstructed/2026-07-31.md"};function i(s,e,u,l,c,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="🔬-科学快报-2026年7月31日-事后重建版-·-第-期" tabindex="-1">🔬 科学快报 | 2026年7月31日（事后重建版 · 第 ? 期） <a class="header-anchor" href="#🔬-科学快报-2026年7月31日-事后重建版-·-第-期" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月31日（事后重建版 · 第 ? 期）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202607310000 TO 202607312359]</code>（cs.AI）｜ 重建日：2026-11-05 当日为周五：Nature 主刊仅发新闻与一则 Author Correction（<code>10.1038/d41586-*</code> 已按规则丢弃），故科学 5 篇取自 Science Advances 12(31) 与 PNAS 123(31) 同日刊出的研究论文。</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🪐-海王星的内卫星与环-是被撞碎天体露出的-冰内部" tabindex="-1">🪐 海王星的内卫星与环，是被撞碎天体露出的&quot;冰内部&quot; <a class="header-anchor" href="#🪐-海王星的内卫星与环-是被撞碎天体露出的-冰内部" aria-label="Permalink to &quot;🪐 海王星的内卫星与环，是被撞碎天体露出的&quot;冰内部&quot;&quot;">​</a></h3><p><strong>Neptune&#39;s inner moons and rings are exposed icy body interiors</strong><em>Science Advances 12(31)（2026-07-31）</em></p><p>加州理工（Caltech）M. Ryleigh Davis、Michael E. Brown 团队与空间望远镜研究所 Ian Wong 用詹姆斯·韦布空间望远镜（JWST）观测了海王星的环，以及 Larissa、Galatea、Proteus 三颗内卫星。它们的近红外光谱在太阳系外天体中独一无二：完全没有水冰的吸收特征，却同时存在很深的 3 微米 OH 带；Larissa、Galatea 与环还共同出现 2.72 微米吸收带——这是富镁层状硅酸盐（phyllosilicate）的诊断特征，意味着曾发生大规模水-岩反应（水蚀变）。这类矿物只能形成于分化天体的内部，因此今日的内卫星与环很可能是由一颗被海卫一（Triton）猛烈俘获过程中摧毁的原始卫星、或被潮汐撕碎的小行星的<strong>深层内部物质</strong>重新吸积而成。这让海王星内系统成为一个罕见的窗口：可以直接读取冰质天体&quot;内部长什么样&quot;，而不必钻进去。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aeb1437" target="_blank" rel="noreferrer">10.1126/sciadv.aeb1437</a></p><h3 id="☀️-非共面多齿锚定分子-稳住了钙钛矿-硅叠层的-被埋界面" tabindex="-1">☀️ 非共面多齿锚定分子，稳住了钙钛矿/硅叠层的&quot;被埋界面&quot; <a class="header-anchor" href="#☀️-非共面多齿锚定分子-稳住了钙钛矿-硅叠层的-被埋界面" aria-label="Permalink to &quot;☀️ 非共面多齿锚定分子，稳住了钙钛矿/硅叠层的&quot;被埋界面&quot;&quot;">​</a></h3><p><strong>Noncoplanar multidentate contacts reinforce buried interface for perovskite/silicon tandem solar cells</strong><em>Science Advances 12(31)（2026-07-31）</em></p><p>南京大学徐欣然、孙洛康等设计了一个非共面构型的多官能团分子 TTA（三苯胺骨架挂三个噻吩羧酸）。在反式钙钛矿电池中，自组装单分子层（SAM，此处为常用的 Me-4PACz）与钙钛矿之间的&quot;被埋界面&quot;决定效率与寿命，但 SAM 分子易脱附、易因 π-π 堆叠团聚。TTA 的非共面几何从空间上阻断了 π-π 堆叠，使分子膜更均匀；噻吩单元与三齿羧基同时抓住衬底与上层钙钛矿，DFT 计算确认了这种多齿配位。结果：1.67 eV 宽带隙钙钛矿单结冠军效率 23.7%，热循环与光照浸泡稳定性提升；钙钛矿/硅叠层效率 33.3%（认证 33.1%），户外实测 30 天无效率损失。这是把&quot;分子几何&quot;而非&quot;配方试错&quot;作为界面工程变量的范例。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aei2945" target="_blank" rel="noreferrer">10.1126/sciadv.aei2945</a></p><h3 id="🌊-深对流把-新鲜-有机碳直接泵进深海" tabindex="-1">🌊 深对流把&quot;新鲜&quot;有机碳直接泵进深海 <a class="header-anchor" href="#🌊-深对流把-新鲜-有机碳直接泵进深海" aria-label="Permalink to &quot;🌊 深对流把&quot;新鲜&quot;有机碳直接泵进深海&quot;">​</a></h3><p><strong>Convection injects labile particulate organic carbon to the deep ocean</strong><em>Science Advances 12(31)（2026-07-31）</em></p><p>巴塞罗那海洋科学研究所（ICM-CSIC）Martí Galí 团队分析在拉布拉多海与伊尔明格海漂流的自主剖面浮标（BGC-Argo）数据，发现 2014–2017 年深对流期间，1000 米深处反复出现冬春季叶绿素 a 荧光峰。颗粒的生物光学性质表明这些不是沉降聚集体的&quot;残渣&quot;，而是被深混合直接带下去的表层新鲜浮游植物碎屑（labile POC）。模式模拟显示，混合驱动的 500–2000 米 POC 供给与对流体积强相关（R²≈0.88），在强对流年份可占该层总供给（混合+沉降）的 33–44%。这改写了一个长期假设：深海碳输入并非只靠&quot;雪&quot;慢慢落，还存在一条随天气剧烈波动的&quot;电梯&quot;。它对深海碳收支、深层水体代谢与侧向输出的年际变化都有直接影响。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aee6883" target="_blank" rel="noreferrer">10.1126/sciadv.aee6883</a></p><h3 id="🧠-麻醉苏醒的性别差异-皮质酮—小胶质细胞—神经元的女性专属通路" tabindex="-1">🧠 麻醉苏醒的性别差异：皮质酮—小胶质细胞—神经元的女性专属通路 <a class="header-anchor" href="#🧠-麻醉苏醒的性别差异-皮质酮—小胶质细胞—神经元的女性专属通路" aria-label="Permalink to &quot;🧠 麻醉苏醒的性别差异：皮质酮—小胶质细胞—神经元的女性专属通路&quot;">​</a></h3><p><strong>Corticosterone-linked microglial activity underpins sexually dimorphic neuroplasticity after ketamine anesthesia</strong><em>Science Advances 12(31)（2026-07-31）</em></p><p>奥地利 ISTA 的 Alessandro Venturino 等发现，氯胺酮麻醉苏醒期存在一条<strong>只在雌性小鼠</strong>中出现的皮质酮介导的小胶质细胞—神经元相互作用，雄性中缺失。该作用伴随微小兴奋性突触后电流（mEPSC）频率升高，即突触层面的可塑性变化；用小胶质细胞清除后这一效应消失（occluded）。分子中介是雌性小胶质细胞中上调的应激共伴侣蛋白 Fkbp5/Fkbp51。为验证因果，作者切除肾上腺（去除皮质酮主要来源）后紧密的小胶质—神经元接触减少，再注射皮质酮又恢复。同日 Nature 新闻 &quot;Brains of male and female mice recover differently from ketamine&quot;（<code>10.1038/d41586-026-02356-0</code>）报道了这项工作，两刊交叉印证。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.adz6517" target="_blank" rel="noreferrer">10.1126/sciadv.adz6517</a></p><h3 id="🎓-ai-工具的采用是-军备竞赛-而非-自由选择-两千名家长的激励相容实验" tabindex="-1">🎓 AI 工具的采用是&quot;军备竞赛&quot;而非&quot;自由选择&quot;：两千名家长的激励相容实验 <a class="header-anchor" href="#🎓-ai-工具的采用是-军备竞赛-而非-自由选择-两千名家长的激励相容实验" aria-label="Permalink to &quot;🎓 AI 工具的采用是&quot;军备竞赛&quot;而非&quot;自由选择&quot;：两千名家长的激励相容实验&quot;">​</a></h3><p><strong>Social dynamics of AI adoption in parents&#39; educational decisions</strong><em>PNAS 123(31)（2026-07-31）</em></p><p>芝加哥大学 Leonardo Bursztyn、Alex Imas、Rafael Jiménez-Durán、Aaron Leonard 与博科尼大学 Christopher Roth 在美国、加拿大、英国约 2000 名家长中做了预注册、激励相容的实验（真实 elicitation 付费意愿）。核心结果：对三个月 AI 高级订阅的支付意愿随&quot;别人家孩子用 AI 的比例&quot;急剧上升——把感知同伴使用率从 20% 提到 80%，支付意愿上升超过 60%。这与&quot;多数人其实希望集体禁用&quot;并不矛盾：这正是典型的<strong>囚徒困境式扩散</strong>，个体理性导致集体次优。第二个实验给出令人不安的结论：提供&quot;AI 可能损害长期技能&quot;的风险信息，显著改变了家长对长期影响的信念，但几乎不改变其付费行为。政策含义明确：单靠风险告知不足以约束这类技术扩散，需要的是协调机制（集体承诺/规则），而不是更多科普。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2533193123" target="_blank" rel="noreferrer">10.1073/pnas.2533193123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🧊-crystalmem-把-记忆-做成可结晶—可重结晶的弹性副车" tabindex="-1">🧊 CrystalMem：把&quot;记忆&quot;做成可结晶—可重结晶的弹性副车 <a class="header-anchor" href="#🧊-crystalmem-把-记忆-做成可结晶—可重结晶的弹性副车" aria-label="Permalink to &quot;🧊 CrystalMem：把&quot;记忆&quot;做成可结晶—可重结晶的弹性副车&quot;">​</a></h3><p><strong>CrystalMem: Elastic Memory for Self-Evolving LLM Agents via Knowledge Crystallization</strong><em>arXiv:2608.00303（2026-07-31）</em></p><p>Beining Wu 与 Jun Huang 指出智能体记忆系统的一个结构性错误假设：字节预算只会增长。现实中云平台会随负载压缩配额，而实验显示&quot;压缩—恢复&quot;后能力<strong>不会回到原位</strong>，作者称之为 <em>memory hysteresis</em>（记忆迟滞）。他们证明：任何只做&quot;保留/丢弃&quot;的策略都存在残余亏空下界——因为删除与单向压缩丢掉了日后重建所需的材料。CrystalMem 用四档保真度状态 + &quot;结晶能量&quot;调度做降级，按优势加权影响度与依赖耦合排序，并在明确的算力/字节上限下通过&quot;验证式重结晶&quot;恢复能力。在 7 个环境、17 种方法、6 个骨干模型上（含多租户服务与真实边缘—云部署）均取得最高恢复能力；50% 字节预算即可追平最强基线在满配额下的表现，同等预算下平均领先 4.6 个百分点。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00303" target="_blank" rel="noreferrer">2608.00303</a></p><h3 id="🔍-分层-bm25-十亿文档上的词典检索-用-4-4-gb-换-300-毫秒" tabindex="-1">🔍 分层 BM25：十亿文档上的词典检索，用 4.4 GB 换 300 毫秒 <a class="header-anchor" href="#🔍-分层-bm25-十亿文档上的词典检索-用-4-4-gb-换-300-毫秒" aria-label="Permalink to &quot;🔍 分层 BM25：十亿文档上的词典检索，用 4.4 GB 换 300 毫秒&quot;">​</a></h3><p><strong>Hierarchical BM25: Lexical Search at Billion-Document Scale</strong><em>arXiv:2608.00229（2026-07-31）</em></p><p>Umesh Deshpande 与 Swaminathan Sundararaman 从工程约束出发：十亿文档的扁平 BM25 索引约 400 GB，驻留内存需与语料同阶的 DRAM，落盘则每查询 4–12 秒——精确 top-k 词典检索在交互延迟预算内不可行。分层 BM25 放弃&quot;精确排序&quot;、只放弃&quot;精确的分组选择&quot;：常驻的粗索引先用两个信号挑出查询要访问的约 1000 个主题均衡分组中的少数几个（查询词在组内的总频次；以及那些分散到频次信号失效的信息词是否在同一文档中共现），随后对选中组穷举检索、用约 100 KB 全局统计打分。因此<strong>返回的每个分数都等于扁平索引的分数</strong>，近似只发生在分组选择上。常驻占用约 4.4 GB 且与语料规模无关；十亿文档上的 16 词查询约 300 ms（吞吐为扁平多线程索引的 4.7–5.6 倍），热缓存约 32 QPS（扁平 ❤️）。在 50 万文档配置下，只访问 5–10% 的簇即可恢复穷举结果的 0.83–0.92 分数。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00229" target="_blank" rel="noreferrer">2608.00229</a></p><h3 id="⚖️-更多辩论-同样证据-同质多智能体评审的结构性上限" tabindex="-1">⚖️ 更多辩论，同样证据：同质多智能体评审的结构性上限 <a class="header-anchor" href="#⚖️-更多辩论-同样证据-同质多智能体评审的结构性上限" aria-label="Permalink to &quot;⚖️ 更多辩论，同样证据：同质多智能体评审的结构性上限&quot;">​</a></h3><p><strong>More Debate, Same Evidence: Structural Limits of Homogeneous Multi-Agent Groundedness</strong><em>arXiv:2608.00243（2026-07-31）</em></p><p>Yuelyu Ji 检验一个被广泛默认的假设：让多个 LLM 组成评审小组互相批评，能提升判断质量。任务选定为&quot;接地性验证&quot;（判断某主张是否被给定证据支持），在 6 个公开的事实核查与幻觉检测基准上评测一个同质三智能体小组。相对固定单智能体参照，系统级准确率差异范围是 <strong>+8.5 到 −4.4 个百分点</strong>：两个数据集显著提升、一个显著下降、三个统计上无法判定。作者同时诚实地指出局限：参照与小组使用了不同模型变体，因此这些差异刻画的是&quot;完整系统&quot;，而非可分离的&quot;辩论因果效应&quot;。结论指向一个朴素但重要的事实——当所有辩手共享同一套证据与同一类先验时，增加辩论轮次不增加信息量。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00243" target="_blank" rel="noreferrer">2608.00243</a></p><h3 id="🎯-同样的数字-不同的结论-ai-智能体的贝叶斯式与动机性推理" tabindex="-1">🎯 同样的数字，不同的结论：AI 智能体的贝叶斯式与动机性推理 <a class="header-anchor" href="#🎯-同样的数字-不同的结论-ai-智能体的贝叶斯式与动机性推理" aria-label="Permalink to &quot;🎯 同样的数字，不同的结论：AI 智能体的贝叶斯式与动机性推理&quot;">​</a></h3><p><strong>Bayesian and Motivated Reasoning in AI Agents</strong><em>arXiv:2608.00339（2026-07-31）</em></p><p>Eddie Yang 做了一个干净的控制实验：固定证据数值不变，只改变证据出现的&quot;情境框定&quot;，观察智能体结论是否变化。在医学、选举取证、地缘政治预测三个高风险领域、12 组&quot;智能体×领域&quot;比较中，结论强烈受先验信念左右——当结论被包装成智能体本来就认为&quot;很可能&quot;的命题时，它更容易给出肯定判断；框定与先验冲突时反之。更值得注意的是框定还改变了<strong>工作方式</strong>：部分智能体检索更广泛、选择不同的分析设定、对同一证据给出不同评价。风险在于：这些先验既未写进任务描述，也不出现在决策记录里，因此外部审计几乎无法从日志中复原&quot;它为什么这么判&quot;。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00339" target="_blank" rel="noreferrer">2608.00339</a></p><h3 id="🧩-心智理论的任务间解离-九个前沿视觉语言模型没有统一的-tom-剖面" tabindex="-1">🧩 心智理论的任务间解离：九个前沿视觉语言模型没有统一的&quot;ToM 剖面&quot; <a class="header-anchor" href="#🧩-心智理论的任务间解离-九个前沿视觉语言模型没有统一的-tom-剖面" aria-label="Permalink to &quot;🧩 心智理论的任务间解离：九个前沿视觉语言模型没有统一的&quot;ToM 剖面&quot;&quot;">​</a></h3><p><strong>Cross-Task Dissociation in Frontier Vision-Language Model Theory of Mind</strong><em>arXiv:2608.00261（2026-07-31）</em></p><p>Kejia Zhang、Youran Sun、Chugang Yi、Haizhao Yang 用两个源自心理学的范式评测同一批 9 个前沿视觉语言模型：Keysar 导演任务（自我中心干扰下的视觉观点采择）与 Frith-Happé 动画三角（从纯运动归因意图，用 Castelli 评分）。结果彼此矛盾：导演任务上，不用思维链时模型像儿童一样在 78% 的试次犯自我中心错误，模型间差异很大，推理能让若干模型&quot;救回来&quot;；动画三角上则普遍<strong>意图归因不足</strong>，其剖面离高功能自闭症成人（HF-ASD）均值比离典型发展成人（TD）均值近三倍以上，而&quot;目标导向&quot;&quot;随机&quot;两项仍接近 TD。没有任何模型在两个任务上都最接近 TD：导演任务上最&quot;成人&quot;的模型在三角上落在 HF-ASD 一侧，三角上最像 TD 的模型在导演任务上却是儿童水平。作者强调这是群体层面的描述，不是对任何模型下诊断标签。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00261" target="_blank" rel="noreferrer">2608.00261</a></p><blockquote><p>📅 日期：2026-07-31 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const p=a(n,[["render",i]]);export{h as __pageData,p as default};
